/** Native offline archive workspace. All long operations run off the UI thread. */
public final class MainActivity extends Activity {
    private static final int PICK_ZIP=40,PICK_FOLDER=41;
    private int background,surface,ink,muted,accent;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final Handler ui=new Handler(Looper.getMainLooper());
    private ChatRepository repository;private ImportSession session;private ChatOrganization organization;private String groupFilter="";
    private LinearLayout root,content,top;private TextView subtitle;private ListView list;
    private boolean importing,searching,destroyed,replaceNext,loadingMessages;
    private int generation;private String selectedChat,selectedTitle,highlight="",page="chats";
    private long throughId;private final List<ChatRepository.Row> visibleMessages=new ArrayList<>();
    @Override public void onCreate(Bundle state){
        AppStyle.apply(this);super.onCreate(state);AppStyle.systemBars(this);AppStyle s=new AppStyle(this);background=s.background;surface=s.surface;ink=s.ink;muted=s.muted;accent=s.accent;
        
        getWindow().setStatusBarColor(background);getWindow().setNavigationBarColor(background);
        organization=new ChatOrganization(this);repository=new ChatRepository(getApplicationContext());session=new ImportSession(getApplicationContext());worker.execute(()->{try{repository.cleanupOrphans();if(getSharedPreferences("display",0).getInt("media_link_version",0)<7){repository.refreshMediaLinks();getSharedPreferences("display",0).edit().putInt("media_link_version",7).apply();}}catch(Exception ignored){}});
        if(state!=null){selectedChat=state.getString("chat");selectedTitle=state.getString("title");replaceNext=state.getBoolean("replaceNext");}
        if(android.os.Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(0,this::navigateBack);
        home();
        if(session.exists())ui.post(()->new AlertDialog.Builder(this).setTitle("Continue the interrupted import?").setMessage("Selected source copies were kept privately on this phone. Current chats are unchanged until the complete import succeeds.").setNegativeButton("Discard",(d,w)->worker.execute(session::discard)).setPositiveButton("Continue",(d,w)->continueSession()).show());
    }
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("chat",selectedChat);state.putString("title",selectedTitle);state.putBoolean("replaceNext",replaceNext);}
    @Override protected void onDestroy(){destroyed=true;ui.removeCallbacksAndMessages(null);worker.shutdownNow();new Thread(()->{try{worker.awaitTermination(30,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException ignored){}if(worker.isTerminated())repository.close();},"close-chat-store").start();super.onDestroy();}
    private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
    private void post(Runnable action){ui.post(()->{if(!destroyed)action.run();});}
    private TextView text(String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);return v;}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private Button button(String title,boolean primary,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextColor(primary?background:ink);b.setTextSize(14);b.setMinHeight(dp(48));b.setBackground(shape(primary?accent:surface,14));b.setPadding(dp(12),dp(8),dp(12),dp(8));b.setOnClickListener(v->action.run());return b;}
    private void space(LinearLayout target,int height){target.addView(new View(this),new LinearLayout.LayoutParams(1,dp(height)));}
    private void horizontalActions(LinearLayout target,String[] names,Runnable[] actions){HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);for(int i=0;i<names.length;i++){Button b=button(names[i],false,actions[i]);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(48));p.rightMargin=dp(8);row.addView(b,p);}scroll.addView(row);target.addView(scroll);}
    private void base(String title,String detail,boolean back){
        generation++;list=null;
        root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(background);
        root.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(dp(16),dp(8)+insets.getSystemWindowInsetTop(),dp(16),dp(4)+insets.getSystemWindowInsetBottom());return insets;});
        setContentView(root);top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);
        if(back)top.addView(button("‹",false,this::navigateBack),new LinearLayout.LayoutParams(dp(48),dp(48)));
        LinearLayout headings=new LinearLayout(this);headings.setOrientation(LinearLayout.VERTICAL);headings.setPadding(back?dp(12):0,dp(12),0,dp(14));TextView h=text(title==null?"Conversation":title,21,ink);h.setTypeface(null,Typeface.BOLD);h.setMaxLines(2);headings.addView(h);subtitle=text(detail,12,muted);headings.addView(subtitle);top.addView(headings,new LinearLayout.LayoutParams(0,-2,1));
        if(!importing&&!back)top.addView(button("⌕",false,()->searchScreen(null,null)),new LinearLayout.LayoutParams(dp(48),dp(48)));
        if(!importing)top.addView(button("⋮",false,this::options),new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(top);
        content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));
        if(!importing){LinearLayout nav=new LinearLayout(this);String[] labels={"Chats","Media","Data","Overview"};Runnable[] go={this::home,()->media(null,null,false),()->startActivity(new Intent(this,MetadataActivity.class)),()->insights("dashboard")};for(int i=0;i<labels.length;i++){Button tab=button(labels[i],false,go[i]);tab.setTextSize(12);tab.setPadding(0,0,0,0);tab.setBackgroundColor(background);nav.addView(tab,new LinearLayout.LayoutParams(0,dp(48),1));}root.addView(nav);}

        TextView privacy=text("OFFLINE · YOUR DATA STAYS ON THIS PHONE",10,muted);privacy.setGravity(Gravity.CENTER);privacy.setPadding(0,dp(9),0,dp(5));root.addView(privacy);root.requestApplyInsets();
    }
    private void home(){
        if(importing)return;selectedChat=null;selectedTitle=null;searching=false;page="chats";loadingMessages=false;base("Snap Explorer","Preparing your local archive…",false);content.addView(new ProgressBar(this));int token=generation;
        worker.execute(()->{try{ChatRepository.Summary stats=repository.summary();List<ChatRepository.Row> rows=repository.chats();post(()->{if(generation!=token)return;content.removeAllViews();if(stats.messages==0&&stats.media==0&&stats.memories==0)welcome();else{
            subtitle.setText(stats.chats+" chats · "+stats.messages+" messages · "+stats.media+" media");
            groupTabs();
            EditText filter=field("Filter conversations by name");content.addView(filter,new LinearLayout.LayoutParams(-1,dp(52)));space(content,8);
            filter.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){String q=s.toString();int request=++generation;worker.execute(()->{List<ChatRepository.Row> found=repository.chatList(q);post(()->{if(request!=generation)return;replaceList(organization.arrange(found,groupFilter),false,r->openChat(r.chat,r.title,0));});});}public void afterTextChanged(android.text.Editable e){}});
            showList(organization.arrange(rows,groupFilter),false,r->openChat(r.chat,r.title,0));
            if(rows.isEmpty())subtitle.setText("Media archive · "+stats.media+" local files · "+stats.memories+" Memories");
        }});}catch(Exception e){post(()->failure("Could not open the local database. Your existing data has not been reset."));}});
    }
    private EditText field(String hint){EditText input=new EditText(this);input.setSingleLine(true);input.setTextColor(ink);input.setHintTextColor(muted);input.setHint(hint);input.setTextSize(15);return input;}
    private void welcome(){ScrollView scroll=new ScrollView(this);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(4),dp(20),dp(4),dp(20));TextView symbol=text("↳",64,accent);card.addView(symbol);TextView h=text("Your history.\nAll in one place.",32,ink);h.setTypeface(null,Typeface.BOLD);card.addView(h);space(card,16);card.addView(text("Read chats, explore media and Memories, see patterns, and create your own archive. Everything happens on this phone.",17,muted));space(card,24);card.addView(button("Import Snapchat ZIPs",true,()->{replaceNext=false;pickZip();}));space(card,10);card.addView(button("Choose an export folder",false,()->{replaceNext=false;pickFolder();}));space(card,10);card.addView(button("Try the sample archive",false,this::demo));space(card,20);card.addView(text("HTML + JSON · MULTIPLE EXPORTS · LOCAL MEDIA\n\nNo account. No uploads. No Internet permission. Imported files stay in this app’s private storage; automatic backups are disabled.\n\nKeep the original export. Missing files cannot be recovered or downloaded by this offline app.",13,muted));scroll.addView(card);content.addView(scroll,new LinearLayout.LayoutParams(-1,-1));}
    private void options(){if(importing)return;new AlertDialog.Builder(this).setTitle("Archive tools").setItems(new String[]{"Import / merge exports","Dashboard & charts","Offline location map","Gallery / slideshow","Export & backup","Verify integrity","Manage source archives","Settings","Privacy & feature status","Clear imported data"},(d,n)->{
        switch(n){case 0:chooseImport();break;case 1:insights("dashboard");break;case 2:insights("map");break;case 3:media(null,null,true);break;case 4:export(selectedChat,selectedTitle);break;case 5:insights("integrity");break;case 6:archives();break;case 7:settings();break;case 8:privacy();break;case 9:clear();break;}
    }).show();}
    private void privacy(){new AlertDialog.Builder(this).setTitle("Offline by design").setMessage("This APK has no Internet permission, telemetry or account. Maps are drawn locally without online tiles. Remote media URLs are never fetched.\n\nPrivate SQLite data, local media and source ZIP copies are not additionally encrypted. Backups/device transfer are disabled. Explicit exports go only to the location you choose.\n\nReply context appears only when the export contains an explicit reference. Deleted/unexported content cannot be recovered.\n\nAndroid media codecs vary: unsupported transcodes are reported rather than silently faked. Desktop Docker hosting and Intel-specific encoding do not run on this phone.").setPositiveButton("Got it",null).show();}
    private void chooseImport(){new AlertDialog.Builder(this).setTitle("Add to your archive").setItems(new String[]{"Merge one or more ZIPs","Merge an export folder","Replace archive with ZIPs"},(d,n)->{replaceNext=n==2;if(n==2)new AlertDialog.Builder(this).setTitle("Replace current import?").setMessage("Only a fully successful import replaces the current data. Your original ZIP files are unchanged.").setNegativeButton("Cancel",null).setPositiveButton("Choose ZIPs",(a,b)->pickZip()).show();else if(n==1)pickFolder();else pickZip();}).show();}
    private void pickZip(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);intent.putExtra(Intent.EXTRA_LOCAL_ONLY,true);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(intent,PICK_ZIP);}
    private void pickFolder(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.putExtra(Intent.EXTRA_LOCAL_ONLY,true);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(intent,PICK_FOLDER);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if((request!=PICK_ZIP&&request!=PICK_FOLDER)||result!=RESULT_OK||data==null)return;
        List<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());if(uris.isEmpty())return;if(uris.size()>32){failure("Choose at most 32 ZIP parts at a time.");return;}
        List<String> labels=new ArrayList<>();for(Uri uri:uris){labels.add(displayName(uri,request==PICK_FOLDER));}
        boolean tree=request==PICK_FOLDER,replace=replaceNext;progress("Preparing selected files…");worker.execute(()->{try{session.start(uris,labels,tree,replace);for(Uri uri:uris)try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}performSession();}catch(Exception|OutOfMemoryError e){post(()->importFailed(e));}});
    }
    private String displayName(Uri uri,boolean folder){if(folder)return "Selected export folder";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()&&c.getString(0)!=null&&!c.getString(0).isEmpty())return c.getString(0);}catch(Exception ignored){}return "Selected Snapchat ZIP";}
    private void progress(String detail){importing=true;selectedChat=null;searching=false;base("Importing locally",detail,false);content.setGravity(Gravity.CENTER);content.addView(new ProgressBar(this));space(content,24);TextView t=text("Keep the app open while it builds your archive.\nSelected source copies can be retried after interruption.\nYour existing data remains until success.",15,muted);t.setGravity(Gravity.CENTER);content.addView(t);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
    private void continueSession(){if(importing)return;progress("Continuing selected import…");worker.execute(()->{try{performSession();}catch(Exception|OutOfMemoryError e){post(()->importFailed(e));}});}
    private void performSession()throws Exception{List<ChatRepository.Input> sources=session.prepare(detail->post(()->subtitle.setText(detail)));ChatRepository.ImportResult result=repository.importArchives(sources,session.replaces(),(done,total)->post(()->subtitle.setText("Processing file "+done+" of "+total)));session.discard();importComplete(result);}
    private void importComplete(ChatRepository.ImportResult result){post(()->{importing=false;getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);home();StringBuilder note=new StringBuilder();note.append(result.messages).append(" new messages\n").append(result.media).append(" new media files\n").append(result.memories).append(" new Memories\n").append(result.archives).append(" source archives added");if(result.duplicateMessages>0||result.duplicateArchives>0)note.append("\n\nSkipped ").append(result.duplicateMessages).append(" duplicate messages and ").append(result.duplicateArchives).append(" previously imported ZIPs.");if(!result.warnings.isEmpty()){note.append("\n\nImport notes:\n");for(int i=0;i<Math.min(8,result.warnings.size());i++)note.append("• ").append(result.warnings.get(i)).append('\n');if(result.warnings.size()>8)note.append("More details may be available in source metadata.");}new AlertDialog.Builder(this).setTitle("Archive ready").setMessage(note.toString()).setPositiveButton("Explore",null).show();});}
    private void importFailed(Throwable e){importing=false;getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);home();String message=e instanceof OutOfMemoryError?"This source needs more memory than the phone can provide. Try smaller export parts.":e instanceof IOException?e.getMessage():"This export could not be parsed, or private storage is unavailable.";new AlertDialog.Builder(this).setTitle("Import didn’t finish").setMessage(message+"\n\nThe previous archive is unchanged. You can retry the selected source copies.").setNegativeButton("Keep for later",null).setNeutralButton("Discard pending",(d,w)->worker.execute(session::discard)).setPositiveButton("Retry",(d,w)->continueSession()).show();}
    private void demo(){if(importing)return;progress("Opening synthetic sample data…");worker.execute(()->{File temp=null;try{temp=File.createTempFile("snap-demo-",".zip",getCacheDir());try(InputStream in=getAssets().open("sample.zip");OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}ChatRepository.ImportResult result=repository.importArchives(Collections.singletonList(new ChatRepository.Input(temp,"Synthetic sample",true)),false,(done,total)->{});importComplete(result);}catch(Exception|OutOfMemoryError e){post(()->importFailed(e));}finally{if(temp!=null)temp.delete();}});}
    private interface Select{void run(ChatRepository.Row row);}
    private void replaceList(List<ChatRepository.Row> rows,boolean messages,Select action){if(list!=null&&list.getParent()==content)content.removeView(list);showList(rows,messages,action);}
    private void showList(List<ChatRepository.Row> rows,boolean messages,Select action){
        if(!messages){showConversations(rows,action);return;}
        list=new ListView(this);list.setDividerHeight(dp(8));list.setDivider(new android.graphics.drawable.ColorDrawable(background));list.setCacheColorHint(background);
        list.setAdapter(new BaseAdapter(){public int getCount(){return rows.size();}public Object getItem(int i){return rows.get(i);}public long getItemId(int i){return i;}public View getView(int pos,View convert,ViewGroup parent){ChatRepository.Row r=rows.get(pos);LinearLayout cell=new LinearLayout(MainActivity.this);cell.setOrientation(LinearLayout.VERTICAL);cell.setPadding(dp(14),dp(12),dp(14),dp(12));cell.setBackground(shape(surface,15));TextView name=text(messages?(searching?r.title+" · ":"")+r.sender:r.title,messages?13:17,messages?accent:ink);name.setTypeface(null,Typeface.BOLD);cell.addView(name);
            if(messages&&r.replyTo!=null&&!r.replyTo.isEmpty()){Button reply=button("↳ View referenced message",false,()->jumpReply(r));cell.addView(reply);}
            TextView body=text(r.text,messages?16:13,messages?ink:muted);body.setPadding(0,dp(6),0,dp(3));body.setLineSpacing(dp(3),1);if(searching){body.setMaxLines(4);body.setEllipsize(android.text.TextUtils.TruncateAt.END);if(!highlight.isEmpty()){String value=r.text.toLowerCase(Locale.ROOT),needle=highlight.toLowerCase(Locale.ROOT);int at=value.indexOf(needle);if(at>=0){SpannableString span=new SpannableString(r.text);span.setSpan(new BackgroundColorSpan(accent),at,Math.min(r.text.length(),at+highlight.length()),0);body.setText(span);}}}else if(messages)body.setTextIsSelectable(true);cell.addView(body);
            if(messages){if(r.mediaRefs!=null&&!r.mediaRefs.equals("[]")){Button attachment=button("View attached media",false,()->openAttachments(r));cell.addView(attachment);}cell.addView(text(AppStyle.date(MainActivity.this,r.time,r.date),11,muted));}
            // Bind the row itself: long-clickable or focusable descendants can stop
            // ListView.onItemClick from receiving the touch. Never rely on it alone.
            if(action!=null){
                cell.setOnClickListener(v->action.run(r));
                if(!messages){
                    Button open=button("Open chat ›",true,()->action.run(r));
                    open.setContentDescription("Open conversation with "+r.title);
                    LinearLayout.LayoutParams openLayout=new LinearLayout.LayoutParams(-1,dp(48));openLayout.topMargin=dp(10);cell.addView(open,openLayout);
                }
            }
            if(messages)cell.setOnLongClickListener(v->{new AlertDialog.Builder(MainActivity.this).setTitle(r.sender).setItems(new String[]{"Copy message","Open conversation","Export conversation"},(d,n)->{if(n==0){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(android.content.ClipData.newPlainText("Message",r.text));Toast.makeText(MainActivity.this,"Copied",Toast.LENGTH_SHORT).show();}else if(n==1)openChat(r.chat,r.title,r.id);else export(r.chat,r.title);}).show();return true;});
            return cell;}});
        list.setOnItemClickListener((parent,view,pos,id)->{if(action!=null)action.run(rows.get(pos));});content.addView(list,new LinearLayout.LayoutParams(-1,0,1));
    }
    private void showConversations(List<ChatRepository.Row> rows,Select action){
        list=new ListView(this);list.setDivider(new android.graphics.drawable.ColorDrawable(surface));list.setDividerHeight(dp(1));
        list.setAdapter(new BaseAdapter(){public int getCount(){return rows.size();}public Object getItem(int n){return rows.get(n);}public long getItemId(int n){return n;}public View getView(int n,View old,ViewGroup parent){
            ChatRepository.Row r=rows.get(n);LinearLayout cell=new LinearLayout(MainActivity.this);cell.setGravity(Gravity.CENTER_VERTICAL);cell.setPadding(dp(2),dp(12),dp(2),dp(12));
            TextView avatar=text(r.title.isEmpty()?"?":r.title.substring(0,1).toUpperCase(Locale.getDefault()),20,accent);avatar.setGravity(Gravity.CENTER);avatar.setBackground(shape(surface,24));cell.addView(avatar,new LinearLayout.LayoutParams(dp(48),dp(48)));
            LinearLayout names=new LinearLayout(MainActivity.this);names.setOrientation(1);names.setPadding(dp(12),0,dp(8),0);TextView name=text(r.title,17,ink);name.setTypeface(null,Typeface.BOLD);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);names.addView(name);TextView preview=text(r.text,13,muted);preview.setPadding(0,dp(4),0,0);if(organization.pinned(r.chat))preview.setText("Pinned · "+r.text);if(!organization.group(r.chat).isEmpty())preview.append(" · "+organization.group(r.chat));names.addView(preview);cell.addView(names,new LinearLayout.LayoutParams(0,-2,1));
            TextView date=text(r.time==0?"":java.time.format.DateTimeFormatter.ofPattern("dd MMM").withZone(ZoneId.systemDefault()).format(Instant.ofEpochMilli(r.time)),11,muted);cell.addView(date);cell.setContentDescription("Open conversation with "+r.title);cell.setOnClickListener(v->action.run(r));cell.setOnLongClickListener(v->{chatOptions(r);return true;});return cell;}});
        list.setOnItemClickListener((p,v,n,id)->action.run(rows.get(n)));content.addView(list,new LinearLayout.LayoutParams(-1,0,1));
    }
    private void groupTabs(){HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout tabs=new LinearLayout(this);List<String> names=new ArrayList<>();names.add("All");names.add("Pinned");names.addAll(organization.groups());for(int i=0;i<names.size();i++){String label=names.get(i),key=i==0?"":i==1?"#pinned":label;Button chip=button(label,key.equals(groupFilter),()->{groupFilter=key;home();});chip.setTextSize(12);if(i>=2)chip.setOnLongClickListener(v->{manageGroup(label);return true;});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(44));p.rightMargin=dp(6);tabs.addView(chip,p);}tabs.addView(button("+ Group",false,()->nameGroup(null,null)),new LinearLayout.LayoutParams(-2,dp(44)));scroll.addView(tabs);content.addView(scroll);space(content,8);}
    private void chatOptions(ChatRepository.Row row){new AlertDialog.Builder(this).setTitle(row.title).setItems(new String[]{organization.pinned(row.chat)?"Unpin chat":"Pin chat","Move to group","Open chat"},(d,n)->{if(n==0){organization.pin(row.chat,!organization.pinned(row.chat));home();}else if(n==1)chooseGroup(row);else openChat(row.chat,row.title,0);}).show();}
    private void chooseGroup(ChatRepository.Row row){List<String> names=new ArrayList<>();names.add("No group");names.addAll(organization.groups());names.add("+ New group");new AlertDialog.Builder(this).setTitle("Group for "+row.title).setItems(names.toArray(new String[0]),(d,n)->{if(n==names.size()-1)nameGroup(null,row.chat);else{organization.move(row.chat,n==0?"":names.get(n));home();}}).show();}
    private void nameGroup(String old,String chat){EditText input=field("Group name");if(old!=null)input.setText(old);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(old==null?"New chat group":"Rename group").setMessage("Organize your local archive. This does not create a Snapchat group.").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String name=input.getText().toString().trim();if(name.isEmpty()||name.length()>40||name.equalsIgnoreCase("All")||name.equalsIgnoreCase("Pinned")||name.startsWith("#")){input.setError("Use a different name, up to 40 characters");return;}for(String existing:organization.groups())if(existing.equalsIgnoreCase(name)&&!existing.equals(old)){input.setError("That group already exists");return;}if(old==null)organization.add(name);else organization.rename(old,name);if(chat!=null)organization.move(chat,name);if(old!=null&&groupFilter.equals(old))groupFilter=name;dialog.dismiss();home();}));dialog.show();}
    private void manageGroup(String name){new AlertDialog.Builder(this).setTitle(name).setItems(new String[]{"Rename group","Remove group (keep chats)"},(d,n)->{if(n==0)nameGroup(name,null);else{organization.remove(name);if(groupFilter.equals(name))groupFilter="";home();}}).show();}
    private void openAttachments(ChatRepository.Row row){int token=generation;worker.execute(()->{List<MediaItem> items=repository.attachments(row);post(()->{if(token!=generation)return;if(items.isEmpty()){new AlertDialog.Builder(this).setTitle("Attachment unavailable").setMessage("No matching local media was included in the imported ZIPs. This offline app cannot download missing files.").setPositiveButton("OK",null).show();return;}if(items.size()==1)media(null,items.get(0).id,false);else{String[] names=new String[items.size()];for(int i=0;i<names.length;i++)names[i]=items.get(i).name;new AlertDialog.Builder(this).setTitle("Local attachments").setItems(names,(d,n)->media(null,items.get(n).id,false)).show();}});});}
    private void jumpReply(ChatRepository.Row row){int token=generation;worker.execute(()->{ChatRepository.Row target=repository.replyTarget(row);post(()->{if(token!=generation)return;if(target==null)Toast.makeText(this,"The referenced message was not included in this export",Toast.LENGTH_LONG).show();else openChat(target.chat,target.title,target.id);});});}
    private void openChat(String id,String title,long target){if(importing)return;startActivity(new Intent(this,ChatActivity.class).putExtra("chat",id).putExtra("title",title).putExtra("target",target));}

    private void loadMessages(boolean older){if(loadingMessages)return;loadingMessages=true;int token=generation;long beforeTime=older&&!visibleMessages.isEmpty()?visibleMessages.get(0).time:0,beforeId=older&&!visibleMessages.isEmpty()?visibleMessages.get(0).id:0;String chat=selectedChat;long target=throughId;if(older&&beforeId==0){loadingMessages=false;return;}worker.execute(()->{try{List<ChatRepository.Row> rows=repository.messages(chat,beforeTime,beforeId,target);post(()->{loadingMessages=false;if(token!=generation)return;if(older&&rows.isEmpty()){Toast.makeText(this,"You’re at the beginning",Toast.LENGTH_SHORT).show();return;}if(older)visibleMessages.addAll(0,rows);else{visibleMessages.clear();visibleMessages.addAll(rows);}replaceList(visibleMessages,true,null);list.setSelection(older?rows.size():Math.max(0,visibleMessages.size()-1));subtitle.setText(visibleMessages.size()+" messages loaded · "+getSharedPreferences("display",0).getString("timezone","UTC"));});}catch(Exception e){post(()->{loadingMessages=false;failure("Could not load this conversation.");});}});}
    private void loadNewer(){if(loadingMessages||visibleMessages.isEmpty())return;loadingMessages=true;ChatRepository.Row last=visibleMessages.get(visibleMessages.size()-1);int token=generation;worker.execute(()->{try{List<ChatRepository.Row> rows=repository.messagesAfter(last.chat,last.time,last.id);post(()->{loadingMessages=false;if(token!=generation)return;if(rows.isEmpty()){Toast.makeText(this,"You’re at the latest message",Toast.LENGTH_SHORT).show();return;}int previous=visibleMessages.size();visibleMessages.addAll(rows);replaceList(visibleMessages,true,null);list.setSelection(previous);});}catch(Exception e){post(()->{loadingMessages=false;failure("Could not load newer messages.");});}});}
    private void jumpDate(){Calendar now=Calendar.getInstance();new DatePickerDialog(this,(view,year,month,day)->{try{ZoneId zone=ZoneId.of(getSharedPreferences("display",0).getString("timezone","UTC"));long epoch=LocalDate.of(year,month+1,day).atStartOfDay(zone).toInstant().toEpochMilli();String chat=selectedChat,title=selectedTitle;worker.execute(()->{long target=repository.messageAtDate(chat,epoch);post(()->{if(target==0)Toast.makeText(this,"No message on or after this date",Toast.LENGTH_LONG).show();else openChat(chat,title,target);});});}catch(Exception e){failure("Choose a valid date.");}},now.get(Calendar.YEAR),now.get(Calendar.MONTH),now.get(Calendar.DAY_OF_MONTH)).show();}
    private void searchScreen(String chat,String title){if(importing)return;selectedChat=chat;selectedTitle=title;searching=true;page="search";base(chat==null?"Search archive":"Find in "+title,"WORDS, SENDERS AND DATES",true);
        EditText query=field("Words or sender name"),since=field("From YYYY-MM-DD (optional)"),until=field("To YYYY-MM-DD (optional)");query.setImeOptions(EditorInfo.IME_ACTION_SEARCH);content.addView(query,new LinearLayout.LayoutParams(-1,dp(52)));LinearLayout dates=new LinearLayout(this);dates.addView(since,new LinearLayout.LayoutParams(0,dp(52),1));dates.addView(until,new LinearLayout.LayoutParams(0,dp(52),1));content.addView(dates);space(content,8);
        Runnable search=()->{String value=query.getText().toString().trim();if(value.isEmpty())return;if(value.length()>200){query.setError("Use fewer words");return;}Long from,to;try{ZoneId zone=ZoneId.of(getSharedPreferences("display",0).getString("timezone","UTC"));from=since.getText().length()==0?null:LocalDate.parse(since.getText().toString()).atStartOfDay(zone).toInstant().toEpochMilli();to=until.getText().length()==0?null:LocalDate.parse(until.getText().toString()).plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli()-1;if(from!=null&&to!=null&&from>to)throw new IllegalArgumentException();}catch(Exception e){since.setError("Use YYYY-MM-DD, with start before end");return;}int token=++generation;highlight=value;worker.execute(()->{try{List<ChatRepository.Row> results=repository.search(value,chat,from,to);post(()->{if(token!=generation)return;subtitle.setText(results.size()==200?"First 200 matches · refine to narrow results":results.size()+" matching messages");replaceList(results,true,r->openChat(r.chat,r.title,r.id));});}catch(Exception e){post(()->{if(token==generation)query.setError("Try a word or sender name");});}});};content.addView(button("Search locally",true,search));space(content,10);query.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH){search.run();return true;}return false;});
    }
    private void archives(){int token=generation;worker.execute(()->{List<String> rows=new ArrayList<>();try(Cursor c=repository.getReadableDatabase().rawQuery("SELECT label,messages,media,imported_at FROM archives ORDER BY imported_at DESC",null)){while(c.moveToNext())rows.add(c.getString(0)+"\n"+c.getInt(1)+" added messages · "+c.getInt(2)+" media");}post(()->{if(token!=generation)return;String detail=rows.isEmpty()?"Your existing v0.1 chats are preserved. Import a source ZIP to enable rebuild and verification.":android.text.TextUtils.join("\n\n",rows);new AlertDialog.Builder(this).setTitle("Source archives").setMessage(detail).setNegativeButton("Close",null).setNeutralButton("Export backup",(d,w)->export(null,"Archive")).setPositiveButton("Rebuild",(d,w)->rebuild()).show();});});}
    private void rebuild(){new AlertDialog.Builder(this).setTitle("Rebuild from retained sources?").setMessage("The app will re-read its private source copies and rebuild messages, media links and indexes. The current archive remains if rebuilding fails. A backup is recommended first.").setNegativeButton("Cancel",null).setPositiveButton("Rebuild",(d,w)->{progress("Checking retained source ZIPs…");worker.execute(()->{try{List<ChatRepository.Input> inputs=repository.retainedSources();if(inputs.isEmpty())throw new IOException("No retained source ZIP is available. Import the original export first.");ChatRepository.ImportResult result=repository.importArchives(inputs,true,(done,total)->post(()->subtitle.setText("Rebuilding file "+done+" of "+total)));importComplete(result);}catch(Exception|OutOfMemoryError e){post(()->importFailed(e));}});}).show();}
    private void settings(){new AlertDialog.Builder(this).setTitle("Display & storage").setItems(new String[]{"Theme","Timezone","Screenshots","Local storage details"},(d,n)->{if(n==0)new AlertDialog.Builder(this).setTitle("Theme").setItems(new String[]{"System","Dark","Light"},(a,i)->{getSharedPreferences("display",0).edit().putString("theme",new String[]{"system","dark","light"}[i]).apply();recreate();}).show();else if(n==1){EditText zone=field("UTC, Asia/Kolkata, Europe/London…");zone.setText(getSharedPreferences("display",0).getString("timezone","UTC"));new AlertDialog.Builder(this).setTitle("Display timezone").setView(zone).setNegativeButton("Cancel",null).setNeutralButton("Phone timezone",(a,b)->{getSharedPreferences("display",0).edit().putString("timezone",ZoneId.systemDefault().getId()).apply();home();}).setPositiveButton("Save",(a,b)->{try{String z=ZoneId.of(zone.getText().toString().trim()).getId();getSharedPreferences("display",0).edit().putString("timezone",z).apply();home();}catch(Exception e){failure("That timezone is not recognised. Try Asia/Kolkata or UTC.");}}).show();}else if(n==2){new AlertDialog.Builder(this).setTitle("Screenshots allowed").setMessage("Screenshots and screen recordings are allowed on every app screen.").setPositiveButton("OK",null).show();}else worker.execute(()->{ChatRepository.Summary stats=repository.summary();long available=getFilesDir().getUsableSpace();post(()->new AlertDialog.Builder(this).setTitle("Private storage").setMessage(stats.archives+" retained ZIPs\n"+stats.media+" media files\n"+(stats.bytes/(1024*1024))+" MB media\n"+(available/(1024*1024))+" MB available\n\nDatabase, media and source copies are local to this app. Automatic cloud backups are disabled.").setPositiveButton("OK",null).show());});}).show();}
    private void clear(){new AlertDialog.Builder(this).setTitle("Clear all imported data?").setMessage("This permanently deletes the app’s messages, media, metadata and retained source copies. Your original selected files are unchanged. Export a backup first if needed.").setNegativeButton("Cancel",null).setPositiveButton("Clear imported data",(d,w)->worker.execute(()->{try{repository.clear();session.discard();post(this::home);}catch(Exception e){post(()->failure("Could not clear the private archive."));}})).show();}
    private void insights(String which){if(importing)return;startActivity(new Intent(this,InsightsActivity.class).putExtra("page",which));}
    private void media(String source,String id,boolean immersive){if(importing)return;Intent intent=new Intent(this,MediaActivity.class).putExtra("immersive",immersive);if(source!=null)intent.putExtra("source",source);if(id!=null)intent.putExtra("media_id",id);startActivity(intent);}
    private void export(String chat,String title){if(importing)return;Intent intent=new Intent(this,ExportActivity.class);if(chat!=null)intent.putExtra("chat",chat);if(title!=null)intent.putExtra("title",title);startActivity(intent);}
    private void failure(String message){if(!destroyed)new AlertDialog.Builder(this).setTitle("Something needs attention").setMessage(message).setPositiveButton("OK",null).show();}
    private void navigateBack(){if(importing){Toast.makeText(this,"Import is active. Keep the app open, or reopen later to retry.",Toast.LENGTH_LONG).show();return;}if(page.equals("search")&&selectedChat!=null){openChat(selectedChat,selectedTitle,0);return;}if(selectedChat!=null||searching){home();return;}finish();}
    @Override public void onBackPressed(){navigateBack();}
}
